/*
   HRMA i18n sözlüğü — i18n_pages.js
   ---------------------------------------------------------------
   Katı yakıtlı motor (solid.html) ve sıvı yakıtlı motor (liquid.html)
   sayfalarının TÜM kullanıcı metinleri. Anahtar önekleri:

     solid.*   katı yakıt sayfası
     liq.*     sıvı yakıt sayfası

   Alt gruplar:
     *.ui.*    şablondaki durağan metinler (data-i18n ile işaretli)
     *.attr.*  title / placeholder nitelikleri
     *.js.*    JS ile üretilen HTML içindeki durağan metinler (T ile)
     *.msg.*   durum/hata iletileri, grafik başlıkları, sütun adları

   Kurallar (tests/test_i18n.py ve tests/test_i18n_pages.py doğruluyor):
     - EN ve TR anahtar kümeleri BİREBİR aynıdır.
     - Anahtar ve değer tek tırnak içinde, satır başına bir çift.
     - Aynı anahtar başka bir sözlük dosyasında tanımlanamaz.
     - Teknik kısaltmalar (Isp, c*, CF, O/F, Kn, L*, BATES, NHNE, STEP,
       DXF) çevrilmez; yerleşik Türkçe karşılığı olan terimler çevrilir
       (chamber pressure -> oda basıncı, nozzle -> nozul, throat -> boğaz,
       regression rate -> regresyon hızı, safety factor -> emniyet katsayısı).
*/
