            'liq.ui.maximum_burn_duration': 'Maximum Burn Duration',
            'liq.ui.maximum_continuous_operation_time_limited_by': 'Maximum continuous operation time. Limited by cooling system capacity, ablative liner life, or propellant supply. Regeneratively cooled: 300-600s, Ablative: 30-300s, affects mission design.',
            'liq.ui.maximum_engine_deflection_angle_for_thrust': 'Maximum engine deflection angle for thrust vector control. Larger angles provide better control authority but increase complexity. Typical: ±5° to ±15°. Limited by plumbing flexibility.',
            'liq.ui.maximum_operating_temperature_limits_component_m': 'Maximum operating temperature. Limits component materials and affects cooling requirements. Desert launch: 320K, Spacecraft: 400K+ in sunlight.',
            'liq.ui.maximum_operational_mixture_ratio_before_excessi': 'Maximum operational mixture ratio before excessive oxidizer causes performance loss and thermal issues. Typically 120-130% of optimal ratio.',
            'liq.ui.maximum_storage_time_before_use_affects': 'Maximum storage time before use. Affects seal materials, propellant stability, component degradation. Launch vehicles: 3-12 months, Spacecraft: 12-60 months on orbit.',
