            'liq.ui.methane_ch4': 'Methane (CH4)',
            'liq.ui.method_for_engine_startup_hypergolic_instant': 'Method for engine startup. Hypergolic: instant ignition, simple. Torch: external igniter first. Spin-start: turbopumps spun up first. Bleed-start: uses stored high-pressure gas.',
            'liq.ui.method_for_initial_combustion_hypergolic_spontan': 'Method for initial combustion. Hypergolic: spontaneous ignition, simple. Torch: external flame source. Spark: electric ignition. Pyrotechnic: solid igniter charge.',
            'liq.ui.method_for_managing_high_chamber_temperatures': 'Method for managing high chamber temperatures (3000K+). Regenerative: fuel/coolant channels, best performance, complex. Ablative: sacrificial liner, simpler, limited reuse. Film: propellant film cooling. Radiation: space engines only.',
            'liq.ui.method_of_attaching_engine_to_vehicle': 'Method of attaching engine to vehicle. Gimbal: provides thrust vector control, heavier. Fixed: lighter, requires separate control system. Determines TVC capability and mass.',
