            'liq.ui.solver_scope_rest': 'Most other numeric fields now reach the solver as range-checked overrides. Fields the solver does not use are flagged next to the input after every run, with the reason: reference only, transient not modelled yet, or computed by the solver. A flagged field is recorded with the design and reaches the reports and exports, but it does not change the computed result. Values the solver sizes itself, such as the throat diameter and the injection velocities, are shown next to your entry so you can compare them.',
