            'liq.ui.maximum_allowable_hot_side_wall_temperature': 'İzin verilen azami sıcak taraf cidar sıcaklığı. Malzeme özellikleri ve (hidrokarbon yakıtlarda) kokslaşma ile sınırlıdır. Çelik: 800 K, Inconel: 1200 K, bakır: 700 K. Motor ömrü için kritiktir.',
            'liq.ui.maximum_burn_duration': 'Azami Yanma Süresi',
            'liq.ui.maximum_continuous_operation_time_limited_by': 'Azami sürekli çalışma süresi. Soğutma sistemi kapasitesi, ablatif astar ömrü veya itici beslemesiyle sınırlıdır. Rejeneratif soğutmalı: 300-600 s, ablatif: 30-300 s; görev tasarımını etkiler.',
            'liq.ui.maximum_engine_deflection_angle_for_thrust': 'İtki vektör denetimi için azami motor sapma açısı. Büyük açılar daha iyi denetim yetkisi verir ama karmaşıklığı artırır. Tipik: ±5° ile ±15°. Boru tesisatının esnekliğiyle sınırlıdır.',
            'liq.ui.maximum_operating_temperature_limits_component_m': 'Azami çalışma sıcaklığı. Bileşen malzemelerini sınırlar ve soğutma gereksinimlerini etkiler. Çölde fırlatma: 320 K, uzay aracı: güneş altında 400 K ve üzeri.',
            'liq.ui.maximum_operational_mixture_ratio_before_excessi': 'Aşırı oksitleyicinin performans kaybına ve ısıl sorunlara yol açmadan önceki azami çalışma karışım oranı. Tipik olarak optimum oranın %120-130\'u.',
            'liq.ui.maximum_storage_time_before_use_affects': 'Kullanımdan önceki azami depolama süresi. Sızdırmazlık malzemelerini, itici kararlılığını ve bileşen bozunmasını etkiler. Fırlatma araçları: 3-12 ay, uzay araçları: yörüngede 12-60 ay.',
            'liq.ui.maximum_wall_temperature': 'Azami Cidar Sıcaklığı',
