            'liq.ui.method_for_engine_startup_hypergolic_instant': 'Motor çalıştırma yöntemi. Hipergolik: anında ateşleme, basit. Meşale: önce dış ateşleyici. Döndürmeli: önce turbopompalar döndürülür. Bleed: depolanmış yüksek basınçlı gaz kullanır.',
            'liq.ui.method_for_initial_combustion_hypergolic_spontan': 'İlk yanmayı başlatma yöntemi. Hipergolik: kendiliğinden ateşleme, basit. Meşale: dış alev kaynağı. Kıvılcım: elektrikle ateşleme. Piroteknik: katı ateşleyici hakkı.',
            'liq.ui.method_for_managing_high_chamber_temperatures': 'Yüksek oda sıcaklıklarını (3000 K üzeri) yönetme yöntemi. Rejeneratif: yakıt/soğutucu kanalları, en iyi performans, karmaşık. Ablatif: feda edilen astar, daha basit, sınırlı tekrar kullanım. Film: itici filmiyle soğutma. Işınım: yalnızca uzay motorları.',
            'liq.ui.method_of_attaching_engine_to_vehicle': 'Motorun araca bağlanma yöntemi. Gimbal: itki vektör denetimi sağlar, ağırdır. Sabit: hafiftir, ayrı bir denetim sistemi ister. TVC yeteneğini ve kütleyi belirler.',
            'liq.ui.minimum_operational_mixture_ratio_for_stable': 'Kararlı yanma için asgari çalışma karışım oranı. Bu oranın altında yanma kararsızlaşır veya eksik kalır. Tipik olarak optimum oranın %70-80\'i.',
            'liq.ui.minimum_throttle_level_as_percentage_of': 'Azami itkinin yüzdesi olarak asgari kısma düzeyi. Derin kısma hassas manevraya ve inişe olanak verir. Gaz jeneratörlü: %40-100, kademeli yanma: %20-100. Yanma kararlılığıyla sınırlıdır.',
