            'liq.ui.solver_scope_rest': 'Diğer sayısal alanların çoğu artık aralık denetiminden geçen geçersiz kılmalar olarak çözücüye ulaşır. Çözücünün kullanmadığı alanlar her hesaptan sonra girdinin yanında gerekçesiyle işaretlenir: yalnızca referans, geçici rejim henüz modellenmiyor ya da çözücü hesaplıyor. İşaretli alan tasarımla birlikte kaydedilir ve raporlara/çıktılara girer, ancak hesaplanan değeri değiştirmez. Boğaz çapı ve püskürtme hızları gibi çözücünün kendi boyutlandırdığı değerler, karşılaştırabilmeniz için girdinizin yanında gösterilir.',
