            'liq.ui.structural_material_for_chamber_walls_steel': 'Oda cidarlarının yapısal malzemesi. Çelik: ucuz, ağır. Alüminyum: hafif, sıcaklık sınırlı. Inconel: yüksek sıcaklık, pahalı. Bakır: soğutma için çok iyi ısı transferi.',
