            'liq.ui.temperature_of_coolant_entering_cooling_system': 'Soğutma sistemine giren soğutucunun sıcaklığı. Genellikle yakıt depolama sıcaklığına yakındır. Kriyojenik yakıtlar: kaynama noktasına yakın. Depolanabilir yakıtlar: ortam sıcaklığı. Soğutma kapasitesini etkiler.',
            'liq.ui.test_fire_requirements': 'Ateşleme Testi Gereksinimleri',
            'liq.ui.the_liquid_fuel_component_rp_1': 'Sıvı yakıt bileşeni. RP-1: rafine kerosen (810 kg/m³), yüksek yoğunluk, oda sıcaklığında depolanabilir. LH2: kriyojenik sıvı hidrojen (71 kg/m³), en yüksek özgül itki, elleçlemesi karmaşık. Metan: ılımlı basınçta depolanabilir (422 kg/m³), Mars görevleri. MMH/UDMH: uzay araçları için hipergolik yakıtlar.',
            'liq.ui.the_liquid_oxidizer_component_lox_cryogenic': 'Sıvı oksitleyici bileşeni. LOX: kriyojenik sıvı oksijen (1141 kg/m³), yüksek performans, yalıtım ister. N2O4: depolanabilir diazot tetroksit (1443 kg/m³), hidrazin yakıtlarıyla hipergolik, zehirli ama uzay araçlarında yaygın.',
            'liq.ui.theoretical_perfect_combustion_ratio_where_all': 'Tüm yakıt ve oksitleyicinin tükendiği kuramsal tam yanma oranı. LOX/RP-1: 3,4, LOX/LH2: 8,0, LOX/metan: 4,0. Gerçek motorlar soğutma ve performans için yakıtça zengin çalışır.',
            'liq.ui.thermal_conductivity_f': 'Isıl İletkenlik λf',
