            'liq.ui.thrust_kn_decreases_with_altitude_due': 'İtki (kN) - geri basınç nedeniyle irtifayla azalır',
            'liq.ui.thrust_n_maximum_thrust_output': 'İtki (N) - azami itki çıkışı',
            'liq.ui.time_constant_for_thrust_changes_during': 'Kısma sırasında itki değişimlerinin zaman sabiti. Hızlı tepki denetim yetkisini artırır ama kararsızlığa yol açabilir. Sistem dinamiği ve vana tepkisiyle sınırlıdır.',
            'liq.ui.time_for_gimbal_actuators_to_respond': 'Gimbal eyleyicilerinin denetim komutlarına tepki süresi. Hızlı tepki aracın kararlılığını ve denetim hassasiyetini artırır. Hidrolik: 10-50 ms, elektrikli: 50-200 ms.',
            'liq.ui.titanium_6al4v': 'Titanyum Ti-6Al-4V',
            'liq.ui.time_from_ignition_command_to_full': 'Ateşleme komutundan tam itkiye kadar geçen süre. Hipergolik: 0,1-0,5 s, gaz jeneratörlü: 1-3 s, kademeli yanma: 3-6 s. Hızlı çalıştırma yer çekimi kayıplarını azaltır ama zorlanmayı artırır.',
            'liq.ui.time_from_shutdown_command_to_zero': 'Kapatma komutundan sıfır itkiye kadar geçen süre. Vana kapanma hızları ve sistem ataletiyle belirlenir. Hızlı kapatma hassasiyeti artırır ama koç darbesi etkisine yol açabilir.',
            'liq.ui.time_required_to_cool_down_hot': 'Yeniden çalıştırmadan önce sıcak bileşenleri soğutmak için gereken süre (kriyojenik motorlar). Hatlarda iticinin buharlaşmasını önler. LOX/LH2: 10-60 s, LOX/RP-1: 5-30 s. Görev takvimini etkiler.',
